//  GENERATED by Crafted from the port's plan (commands.json and the unit contracts). Do not edit: a new plan
//  writes it again.

import Foundation

/// Every field a call may give, all optional: the command, its arguments (a command checks the ones it needs),
/// and the fields every command shares. The host fills `directory`.
public struct AgentInput: Codable, Sendable {
    /// Which command to run; left out, the host's model reads one from `brief`.
    public var command: Command?
    /// the bill before the tip, in its currency
    public var bill: Double?
    /// the tip as a percentage of the bill; left out, the level of service sets it
    public var percent: Double?
    /// the level of service when no percent is given: good when left out
    public var service: ServiceChoice?
    /// how many people share the bill, one or more
    public var people: Int?
    /// what the person wants, in their words, when `command` is left out: the host's model reads it into a command
    public var brief: String?
    /// a crafted-handoff/1 file an upstream agent wrote, relative to the project, for the command to start from
    public var handoff: String?
    /// how the results are written: output (files, the default), canvas (pictures, paged PDFs and series Canvas
    /// shows) or context (one hand-off file for the next agent)
    public var present: Presentation?
    /// the folder the files go in, relative to the project: skeletonword/ when left out
    public var output: String?
    /// the seed for anything random: the same seed makes the same result
    public var seed: Int?
    /// The host's folder.
    public var directory: String?

    public init(command: Command? = nil, bill: Double? = nil, percent: Double? = nil, service: ServiceChoice? = nil, people: Int? = nil, brief: String? = nil, handoff: String? = nil, present: Presentation? = nil, output: String? = nil, seed: Int? = nil, directory: String? = nil) {
        self.command = command
        self.bill = bill
        self.percent = percent
        self.service = service
        self.people = people
        self.brief = brief
        self.handoff = handoff
        self.present = present
        self.output = output
        self.seed = seed
        self.directory = directory
    }
}
